  match a with SA (EAlu ALU_SRL (EVar 36) (ELit 3)) _ => true | _ => false end.
Definition mentions36 (K : kentry) : bool := negb (kentry_vars_lt 36 K).
Definition keepX (K : kentry) : bool :=
  match K with
