Definition jfromB (s : acs) (l : list dstep) : acs := snd (dpath BSEGS IT ABOTH (XN IT NXF) XB BFUEL NXF s l 0).
Definition kmem (K : kentry) (k : list kentry) : bool := existsb (APC.kentry_eqb K) k.
Definition kcommon (s0 : acs) (ss : list acs) : list kentry := List.filter (fun K => forallb (fun s => kmem K (kn s)) ss) (kn s0).
Fixpoint jregs_slots (rs : list expr) (rss : list (list expr)) (i v : nat) (ov : list (nat * expr)) : list expr :=
  match rs with
  | [] => []
  | r :: rs' =>
      match find (fun p => Nat.eqb (fst p) i) ov with
      | Some (_, e) => e :: jregs_slots rs' rss (Datatypes.S i) v ov
      | None =>
          if forallb (fun l => expr_eqb (nth i l (ELit 0)) r) rss then r :: jregs_slots rs' rss (Datatypes.S i) v ov
          else EVar v :: jregs_slots rs' rss (Datatypes.S i) (Datatypes.S v) ov
      end
  end.
Definition svars (a : saddr) (acc : list nat) : list nat := expr_vars (a_base a) acc.
Definition kvars (K : kentry) : list nat :=
  match K with
  | KWord a _ v => svars a (expr_vars v [])
  | KZero a n => svars a (expr_vars n [])
  | KBlob a n _ => svars a (expr_vars n [])
  | KImg _ _ => []
  | KAlign e _ => expr_vars e []
  | KRange e _ _ => expr_vars e []
  | KWr a n => svars a (expr_vars n [])
  | KDisj a1 n1 a2 n2 => svars a1 (expr_vars n1 (svars a2 (expr_vars n2 [])))
  | KFill a n _ => svars a (expr_vars n [])
  | KUnk a n => svars a (expr_vars n [])
  | KShOk a n => svars a (expr_vars n [])
  | KFpc v lo _ => expr_vars v (expr_vars lo [])
  end.
Definition kmentions (vs : list nat) (K : kentry) : bool := existsb (fun v => existsb (Nat.eqb v) vs) (kvars K).
Definition HCB (code : Z) : Z := match code with 0 => 1 | 1 => 2 | 2 => 4 | _ => 8 end.
Definition jarmB (obase : expr) (R : nat) (bigpc joinpc : Z) (c : Z) : list dstep :=
  let hc := HCB c in
  [DRLo R c; DRHi R (c - 1)] ++ (if Z.eqb hc 1 then [] else [DHi (esub (esub EE B) obase) (hc - 1)]) ++
  (if Z.eqb hc 8 then [DRun [bigpc]; DBrF] else []) ++ [DRun [joinpc]].
Definition jtB (s_pre : acs) (obase : expr) (R : nat) (bigpc joinpc : Z) (rc rsp : nat) (rsp_ov : bool) (t : Z) : acs :=
  let st := fun c => jfromB s_pre (jarmB obase R bigpc joinpc c) in
  let s0 := st 0 in let ss := map st [1; 2; 3] in
  let r0 := nth rsp (s_regs (a_ss s_pre)) (ELit 0) in
  let ov := (rc, JCNT) :: (R, EVar 230) :: (if rsp_ov then (if expr_eqb (nth rsp (s_regs (a_ss s0)) (ELit 0)) r0 then [(rsp, ELit t)] else []) else [(rsp, EVar 231)]) in   (* [comment removed for export] *)
  let drop := expr_vars r0 [] in
  let regs := jregs_slots (s_regs (a_ss s0)) (map (fun s => s_regs (a_ss s)) ss) 0%nat 201%nat ov in
  let kq := List.filter (fun K => negb (kmentions drop K) && match K with KWord (SA b 0) _ _ => negb (expr_eqb b Q) | _ => true end) (kcommon s0 ss) in
  let kj := [KWord (SA Q 0) 8 (eadd B JO); KRange JO 0 BUFMAX; KRange (esub (esub EE B) JO) 0 BUFMAX; KRange (esub JO obase) 1 8;
             KRange JCNT 0 (2 ^ 48)] in
  with_ss s0 (mk_ss joinpc regs (kj ++ kq) 240%nat).
